<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { anularSalida, buscarPedidos, guardarSalida, listarSalidas, obtenerSalida, urlNotaSalida } from '../services/salidas'
import type { PedidoSalida, SalidaAlmacen } from '../interfaces/salidas.interface'
import type { PeriodoAlmacen, TipoIngreso } from '../interfaces/ingresos.interface'
const rows=ref<SalidaAlmacen[]>([]),tipos=ref<TipoIngreso[]>([]),periodo=ref<PeriodoAlmacen|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),detail=ref<SalidaAlmacen|null>(null),modal=ref(false),pedidoSearch=ref(''),pedidos=ref<PedidoSalida[]>([]),selected=ref<PedidoSalida|null>(null)
const filters=reactive({criterio:'',tipo_id:'',desde:'',hasta:''}),form=reactive({tipo_id:0,pedido_id:0,entregado_a_id:0,notas:'',items:[] as Array<{item_id:number;item:string;unidad:string;cantidad:number;disponible:number;precio_medio:number}>})
const formTotal=computed(()=>form.items.reduce((sum,x)=>sum+x.cantidad*x.precio_medio,0))
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarSalidas({...filters,page:next});rows.value=r.data;tipos.value=r.tipos;periodo.value=r.periodo;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',tipo_id:'',desde:'',hasta:''});load(1)}
function openCreate(){if(periodo.value&&!periodo.value.abierto){error.value='El periodo de almacén está cerrado.';return}Object.assign(form,{tipo_id:tipos.value[0]?.id||0,pedido_id:0,entregado_a_id:0,notas:'',items:[]});pedidoSearch.value='';pedidos.value=[];selected.value=null;modal.value=true}
async function searchOrders(){if(!pedidoSearch.value.trim())return;try{pedidos.value=await buscarPedidos(pedidoSearch.value)}catch(e){error.value=message(e)}}
function choose(pedido:PedidoSalida){selected.value=pedido;form.pedido_id=pedido.id;form.items=pedido.items.map(x=>({item_id:x.item_id,item:x.item,unidad:x.unidad,cantidad:Math.max(0,Math.min(x.cantidad_pedida-x.cantidad_atendida,x.stock_comprometido)),disponible:Math.min(x.cantidad_pedida-x.cantidad_atendida,x.stock_comprometido),precio_medio:x.precio_medio}))}
function validate(){if(!form.tipo_id)return 'Seleccione el tipo de salida.';if(!form.pedido_id)return 'Seleccione un pedido aprobado.';if(!form.entregado_a_id)return 'Indique la persona que recibe los materiales.';if(!form.notas.trim())return 'Ingrese las notas de entrega.';if(!form.items.length)return 'El pedido no contiene ítems pendientes.';if(form.items.some(x=>x.cantidad<=0||x.cantidad>x.disponible))return 'Las cantidades deben ser mayores a cero y no superar el stock comprometido.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarSalida({tipo_id:form.tipo_id,pedido_id:form.pedido_id,entregado_a_id:form.entregado_a_id,notas:form.notas,items:form.items.map(x=>({item_id:x.item_id,cantidad:x.cantidad}))});modal.value=false;success.value='Salida registrada y stock actualizado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:SalidaAlmacen){try{detail.value=await obtenerSalida(item.id)}catch(e){error.value=message(e)}}
function canCancel(item:SalidaAlmacen){if(item.anulado||!periodo.value?.abierto)return false;const d=new Date(`${item.fecha_operacion}T00:00:00`);return d>=new Date(`${periodo.value.fecha_inicio}T00:00:00`)&&d<=new Date(`${periodo.value.fecha_fin}T23:59:59`)}
async function cancel(item:SalidaAlmacen){if(!canCancel(item))return;const motivo=prompt(`Motivo de anulación de la salida #${item.id}:`)?.trim();if(!motivo)return;if(!confirm('La anulación devolverá las cantidades al stock y al compromiso del pedido. ¿Continuar?'))return;try{await anularSalida(item.id,item.almacen_id,motivo);success.value='Salida anulada correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Salidas</nav><header class="hero"><div class="mark">SA</div><div><small>MIA · ALMACÉN</small><h1>Salidas de almacén</h1><p>Entrega materiales comprometidos en pedidos aprobados.</p></div><div class="period"><small>PERIODO</small><b>{{periodo?.nombre||'Sin periodo'}}</b><span>{{periodo?.abierto?'Abierto':'Cerrado'}}</span></div><button :disabled="periodo?.abierto===false" @click="openCreate">+ Nueva salida</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p>
<section class="filters"><label>N° salida<input v-model.trim="filters.criterio" placeholder="Número de nota" @keyup.enter="load(1)"></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><label>Tipo<select v-model="filters.tipo_id"><option value="">Todos</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Buscar</button><button class="soft" @click="clear">Limpiar</button></section><div v-if="loading" class="empty">Cargando salidas…</div><div v-else-if="!rows.length" class="empty">No se encontraron movimientos de salida.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{cancelled:item.anulado}"><header><div class="icon">↗</div><div><small>NOTA DE SALIDA</small><h2>Salida #{{item.id}}</h2></div><span>{{item.anulado?'ANULADA':'VIGENTE'}}</span></header><dl><div><dt>Tipo</dt><dd>{{item.tipo}}</dd></div><div><dt>Fecha</dt><dd>{{item.fecha_operacion}}</dd></div><div><dt>Pedido</dt><dd>{{item.pedido||'—'}}</dd></div><div><dt>Entregado a</dt><dd>{{item.entregado_a}}</dd></div><div><dt>Ítems / Valor</dt><dd>{{item.items_count}} · {{money(item.valor_total)}}</dd></div></dl><footer><button @click="show(item)">Ver detalle</button><a :href="urlNotaSalida(item.id,item.almacen_id)" target="_blank">Imprimir nota</a><button class="danger" :disabled="!canCancel(item)" @click="cancel(item)">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}} · {{total}} registros</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>DETALLE DEL MOVIMIENTO</small><h2>Salida #{{detail.id}}</h2></div><button @click="detail=null">×</button></header><p>{{detail.tipo}} · {{detail.fecha_operacion}} · {{detail.entregado_a}}</p><table><thead><tr><th>Ítem</th><th>Unidad</th><th>Cantidad</th><th>Precio medio</th><th>Total</th></tr></thead><tbody><tr v-for="line in detail.detalles||[]" :key="line.id"><td>{{line.item}}</td><td>{{line.unidad}}</td><td>{{line.cantidad}}</td><td>{{money(line.precio_unitario)}}</td><td>{{money(line.valor_total)}}</td></tr></tbody></table><footer><b>Total {{money(detail.valor_total)}}</b><button @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>ATENCIÓN DE PEDIDO</small><h2>Registrar salida</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de salida *<select v-model.number="form.tipo_id"><option :value="0">Seleccione</option><option v-for="x in tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Persona que recibe (ID) *<input v-model.number="form.entregado_a_id" type="number" min="1"></label></div><section class="pedido-search"><label>Pedido aprobado *<span><input v-model.trim="pedidoSearch" placeholder="Número, área o solicitante" @keyup.enter.prevent="searchOrders"><button type="button" @click="searchOrders">Buscar</button></span></label><button v-for="p in pedidos" :key="p.id" type="button" class="result" @click="choose(p)"><b>{{p.numero}}</b><span>{{p.area}} · {{p.solicitante}}</span></button><p v-if="selected">Seleccionado: <b>{{selected.numero}}</b> — {{selected.area}}</p></section><label>Notas de entrega *<textarea v-model.trim="form.notas" rows="2" maxlength="500"></textarea></label><div v-if="form.items.length" class="lines"><div class="line head"><b>Ítem</b><b>Unidad</b><b>Disponible</b><b>Cantidad</b><b>Valor</b></div><div v-for="line in form.items" :key="line.item_id" class="line"><span>{{line.item}}</span><span>{{line.unidad}}</span><span>{{line.disponible}}</span><input v-model.number="line.cantidad" type="number" min="0.0001" :max="line.disponible" step="0.0001"><b>{{money(line.cantidad*line.precio_medio)}}</b></div></div><footer><b>Total {{money(formTotal)}}</b><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Registrar salida'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark,.icon{display:grid;place-items:center;color:#fff;background:var(--accent);font-weight:700}.mark{width:50px;height:50px;border-radius:10px;font-size:.65rem}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.5rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>button,.filters button,.pages button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.55rem}.period{margin-left:auto;padding:7px 10px;border-radius:7px;background:#f5f7f8}.period>*{display:block}.period b{font-size:.6rem}.period span{color:#27835e;font-size:.5rem}.flash{padding:9px;border-radius:7px;color:#287052;background:#edf9f3;font-size:.6rem}.flash.error{color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr 1fr 1.3fr auto auto;align-items:end;gap:7px;border-radius:9px;background:#fff}label{display:block;font-size:.53rem}input,select,textarea{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.58rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.62rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #e38b35;border-radius:9px;background:#fff}.cards article.cancelled{opacity:.68;border-top-color:#c34b52}.cards article>header{display:flex;align-items:center;gap:8px}.icon{width:35px;height:35px;border-radius:8px;background:#e38b35}.cards h2{margin:2px 0;font-size:.68rem}.cards header span{margin-left:auto;padding:4px 7px;border-radius:10px;color:#277254;background:#e7f7ef;font-size:.46rem}.cards dl{margin:10px 0}.cards dl div{padding:5px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.52rem}.cards dd{margin-left:auto;text-align:right}.cards dt{color:#78868d}.cards footer{display:flex;gap:6px}.cards footer button,.cards footer a{border:0;color:#a66525;background:none;text-decoration:none;font-size:.5rem}.cards footer .danger{margin-left:auto;color:#bd4149}.cards footer button:disabled{color:#afb6b9}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.53rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:90vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog>p{font-size:.58rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pedido-search{margin:10px 0;padding:10px;border-radius:8px;background:#f6f8f9}.pedido-search label span{display:flex;gap:5px}.result{width:100%;margin-top:5px;display:flex!important;text-align:left;background:#fff!important;color:#45545b!important;border:1px solid #e0e5e7!important}.result span{margin-left:auto}.pedido-search p{font-size:.54rem}.lines{margin:12px 0;border:1px solid #e3e8ea;border-radius:7px}.line{padding:7px;display:grid;grid-template-columns:2fr .6fr .7fr .8fr .8fr;align-items:center;gap:6px;border-bottom:1px solid #edf0f1;font-size:.52rem}.line input{margin:0}.line.head{color:#69777e;background:#f4f6f7}.dialog>footer{display:flex;justify-content:flex-end;align-items:center;gap:7px}.dialog>footer>b{margin-right:auto;font-size:.65rem}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:8px;border-bottom:1px solid #e5e9eb;text-align:left}th{background:#f4f6f7}@media(max-width:850px){.hero{flex-wrap:wrap}.period{margin-left:0}.filters,.grid{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr}.line{grid-template-columns:1fr 1fr}.dialog{padding:14px}}
</style>
